        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the incorrect logic used to check the `GIB_FCS_STRIP` bit for SYSTEMPORT Lite, which resulted in an extra 4 bytes being forwarded to the network stack when the Ethernet Frame Check Sequence (FCS) was stripped. The original implementation did not account for the fact that the `GIB_FCS_STRIP` bit is set when the FCS is stripped, leading to improper handling of CRC forwarding.

        Commit message:
        net: systemport: Fix CRC forwarding check for SYSTEMPORT Lite

SYSTEMPORT Lite reversed the logic compared to SYSTEMPORT, the
GIB_FCS_STRIP bit is set when the Ethernet FCS is stripped, and that bit
is not set by default. Fix the logic such that we properly check whether
that bit is set or not and we don't forward an extra 4 bytes to the
network stack.

Fixes: 44a4524c54af ("net: systemport: Add support for SYSTEMPORT Lite")
Signed-off-by: Florian Fainelli <f.fainelli@gmail.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:

 static int bcm_sysport_open(struct net_device *dev)
 {
 	struct bcm_sysport_priv *priv = netdev_priv(dev);
 	struct phy_device *phydev;
 	unsigned int i;
 	int ret;

 	/* Reset UniMAC */
 	umac_reset(priv);

 	/* Flush TX and RX FIFOs at TOPCTRL level */
 	topctrl_flush(priv);

 	/* Disable the UniMAC RX/TX */
 	umac_enable_set(priv, CMD_RX_EN | CMD_TX_EN, 0);

 	/* Enable RBUF 2bytes alignment and Receive Status Block */
 	rbuf_init(priv);

 	/* Set maximum frame length */
 	if (!priv->is_lite)
 		umac_writel(priv, UMAC_MAX_MTU_SIZE, UMAC_MAX_FRAME_LEN);
 	else
 		gib_set_pad_extension(priv);

 	/* Set MAC address */
 	umac_set_hw_addr(priv, dev->dev_addr);

 	/* Read CRC forward */
 	if (!priv->is_lite)
 		priv->crc_fwd = !!(umac_readl(priv, UMAC_CMD) & CMD_CRC_FWD);
 	else
-		priv->crc_fwd = !!(gib_readl(priv, GIB_CONTROL) &
-				   GIB_FCS_STRIP);
+		priv->crc_fwd = !((gib_readl(priv, GIB_CONTROL) &
+				  GIB_FCS_STRIP) >> GIB_FCS_STRIP_SHIFT);

 	phydev = of_phy_connect(dev, priv->phy_dn, bcm_sysport_adj_link,
 				0, priv->phy_interface);
 	if (!phydev) {
 		netdev_err(dev, "could not attach to PHY\n");
 		return -ENODEV;
 	}

 	/* Reset house keeping link status */
 	priv->old_duplex = -1;
 	priv->old_link = -1;
 	priv->old_pause = -1;

 	/* mask all interrupts and request them */
 	bcm_sysport_mask_all_intrs(priv);

 	ret = request_irq(priv->irq0, bcm_sysport_rx_isr, 0, dev->name, dev);
 	if (ret) {
 		netdev_err(dev, "failed to request RX interrupt\n");
 		goto out_phy_disconnect;
 	}

 	if (!priv->is_lite) {
 		ret = request_irq(priv->irq1, bcm_sysport_tx_isr, 0,
 				  dev->name, dev);
 		if (ret) {
 			netdev_err(dev, "failed to request TX interrupt\n");
 			goto out_free_irq0;
 		}
 	}

 	/* Initialize both hardware and software ring */
 	for (i = 0; i < dev->num_tx_queues; i++) {
 		ret = bcm_sysport_init_tx_ring(priv, i);
 		if (ret) {
 			netdev_err(dev, "failed to initialize TX ring %d\n",
 				   i);
 			goto out_free_tx_ring;
 		}
 	}

 	/* Initialize linked-list */
 	tdma_writel(priv, TDMA_LL_RAM_INIT_BUSY, TDMA_STATUS);

 	/* Initialize RX ring */
 	ret = bcm_sysport_init_rx_ring(priv);
 	if (ret) {
 		netdev_err(dev, "failed to initialize RX ring\n");
 		goto out_free_rx_ring;
 	}

 	/* Turn on RDMA */
 	ret = rdma_enable_set(priv, 1);
 	if (ret)
 		goto out_free_rx_ring;

 	/* Turn on TDMA */
 	ret = tdma_enable_set(priv, 1);
 	if (ret)
 		goto out_clear_rx_int;

 	/* Turn on UniMAC TX/RX */
 	umac_enable_set(priv, CMD_RX_EN | CMD_TX_EN, 1);

 	bcm_sysport_netif_start(dev);

 	return 0;

 out_clear_rx_int:
 	intrl2_0_mask_set(priv, INTRL2_0_RDMA_MBDONE | INTRL2_0_TX_RING_FULL);
 out_free_rx_ring:
 	bcm_sysport_fini_rx_ring(priv);
 out_free_tx_ring:
 	for (i = 0; i < dev->num_tx_queues; i++)
 		bcm_sysport_fini_tx_ring(priv, i);
 	if (!priv->is_lite)
 		free_irq(priv->irq1, dev);
 out_free_irq0:
 	free_irq(priv->irq0, dev);
 out_phy_disconnect:
 	phy_disconnect(phydev);
 	return ret;
 }



